import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import { toIsoTimestamp } from "@/types/common";
import { issueHref, issueHrefById } from "./_links";
import { notificationResource, requireFound } from "./_support";
''')
tail='''/**
 * The bus wiring. Attached at module load rather than from `event-registry`
 * because the fan-out has no other public entry point — importing this module
 * is what makes an org start receiving notifications.
 */
let registered = false;

function registerFanOut(): void {
  if (registered) return;
  registered = true;

  subscribe("issue.created", async (payload) => {
    // Assigned at creation is an assignment; a self-assigned author is skipped by `notify`.
    if (payload.assigneeId === null) return;
    await notifyAssigned(
      payload.orgId,
      payload.issueId,
      payload.assigneeId,
      payload.actorId,
    );
  });

  subscribe("issue.assigned", async (payload) => {
    await notifyAssigned(
      payload.orgId,
      payload.issueId,
      payload.assigneeId,
      payload.actorId,
    );
  });

  subscribe("issue.status_changed", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue || issue.assigneeId === null) return;

    const href = await issueHref(payload.orgId, issue);
    if (href === null) return;

    await notify(payload.orgId, "issue_status_changed", [issue.assigneeId], {
      title: "An issue you are assigned to changed status",
      body: `Issue ${payload.issueId} moved from ${payload.from} to ${payload.to}`,
      href,
      actorId: payload.actorId,
    });
  });

  subscribe("issue.overdue", async (payload) => {
    if (payload.assigneeId === null) return;
    const href = await issueHrefById(payload.orgId, payload.issueId);
    if (href === null) return;

    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
      title: "An issue is overdue",
      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
      href,
      actorId: null,
    });
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue) return;

    const href = await issueHref(payload.orgId, issue);
    if (href === null) return;

    const watchers = [
      issue.authorId,
      ...(issue.assigneeId ? [issue.assigneeId] : []),
    ];

    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href,
      actorId: payload.actorId,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${payload.issueId}`,
          href,
          actorId: payload.actorId,
        },
      );
    }
  });

  // The owner is told who joined. The joiner is passed as the actor so `notify`
  // never tells them about themselves.
  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    const owners = await memberRepo.listOwnerIds(payload.orgId);
    await notify(payload.orgId, "member_joined", owners, {
      title: "A new member joined",
      body: `${payload.userId} joined ${org.name} as ${payload.role}`,
      href: settingsPath(org.slug, "members"),
      actorId: payload.userId,
    });
  });

  // Only refusals alert; the periodic recount reports with `refused: false`.
  // An owner who already has this alert unread gets no second one.
  subscribe("billing.limit_exceeded", async (payload) => {
    if (!payload.refused) return;

    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    const title = `Plan limit reached: ${payload.resource}`;

    const fresh: UserId[] = [];
    for (const ownerId of await memberRepo.listOwnerIds(payload.orgId)) {
      const pending = await notificationRepo.hasUnreadNotification(
        payload.orgId,
        ownerId,
        "plan_limit_reached",
        title,
      );
      if (!pending) fresh.push(ownerId);
    }

    await notify(payload.orgId, "plan_limit_reached", fresh, {
      title,
      body: `${payload.used} of ${payload.limit} in use; upgrade to add more`,
      href: settingsPath(org.slug, "billing"),
      actorId: null,
    });
  });
}

/** Tells one assignee; shared by creation-time and later assignment. */
async function notifyAssigned(
  orgId: OrgId,
  issueId: IssueId,
  assigneeId: UserId,
  actorId: UserId | null,
): Promise<void> {
  const href = await issueHrefById(orgId, issueId);
  if (href === null) return;

  await notify(orgId, "issue_assigned", [assigneeId], {
    title: "You were assigned an issue",
    body: `Issue ${issueId} is now yours`,
    href,
    actorId,
  });
}

registerFanOut();
